const fs = require('fs');

const SIZES = [
  { name: 'portrait', w: 1080, h: 1350, s: 1 },
  { name: 'wide', w: 1200, h: 1000, s: 0.85 },
  { name: 'sky', w: 300, h: 600, s: 0.28 },
];

const html = (cfg) => `<!DOCTYPE html>
<html lang="en"><head><meta charset="utf-8">
<title>Willowmere Forward</title>
<style>
@font-face{
  font-family:'Inter';
  src:url('Inter.ttf') format('truetype-variations');
  font-weight:100 900;
  font-style:normal;
  font-display:block;
}
*{margin:0;padding:0;box-sizing:border-box;}
html,body{width:${cfg.w}px;height:${cfg.h}px;overflow:hidden;}
body{
  font-family:'Inter',sans-serif;
  background:#fff;
  -webkit-font-smoothing:antialiased;
  text-rendering:geometricPrecision;
}
:root{
  --s:${cfg.s};
  --navy:#1B2A5C;
  --red:#D0202E;
  --pad:calc(56px * var(--s));
}
.flyer{
  width:${cfg.w}px;height:${cfg.h}px;
  display:flex;flex-direction:column;align-items:stretch;
  overflow:hidden;position:relative;background:#fff;
}
.band{width:100%;}
.inset{padding-left:var(--pad);padding-right:var(--pad);}

/* ---------- headline ---------- */
.head{
  color:var(--navy);
  font-weight:800;
  font-size:calc(70px * var(--s));
  line-height:1.05;
  letter-spacing:calc(-0.018em);
  text-wrap:balance;
}
.head .hl{color:var(--red);}
.rule{
  height:calc(8px * var(--s));
  width:calc(150px * var(--s));
  background:var(--red);
  border-radius:calc(4px * var(--s));
  margin-top:calc(18px * var(--s));
}

/* ---------- photo ---------- */
.photo{
  width:100%;
  overflow:hidden;
  flex:0 0 auto;
  background:#8ab6e8;
  position:relative;
}
.photo img{width:100%;height:100%;object-fit:cover;object-position:center 42%;display:block;}

/* ---------- candidates ---------- */
.cands{
  display:flex;
  align-items:flex-start;
  width:100%;
}
.cand{
  flex:1 1 0;
  min-width:0;
  text-align:center;
  padding:0 calc(4px * var(--s));
  position:relative;
}
.cand + .cand::before{
  content:"";position:absolute;left:0;top:calc(4px * var(--s));
  width:1px;height:calc(100% - 8px * var(--s));
  background:rgba(27,42,92,.16);
}
.cand .name{
  color:var(--navy);
  font-weight:700;
  font-size:calc(36px * var(--s));
  line-height:1.15;
  letter-spacing:calc(-0.01em);
  white-space:nowrap;
}
.cand .role{
  color:var(--red);
  font-weight:600;
  font-size:calc(21px * var(--s));
  line-height:1.2;
  letter-spacing:calc(0.1em);
  text-transform:uppercase;
  margin-top:calc(8px * var(--s));
  white-space:nowrap;
}

/* ---------- CTA ---------- */
.cta{
  background:var(--red);
  width:100%;
  display:flex;align-items:center;justify-content:center;
  gap:calc(22px * var(--s));
  padding:calc(24px * var(--s)) calc(10px * var(--s));
  flex:0 0 auto;
}
.cta img{
  width:calc(56px * var(--s));
  height:calc(44px * var(--s));
  display:block;flex:0 0 auto;
}
.cta .txt{
  color:#fff;font-weight:800;
  font-size:calc(46px * var(--s));
  line-height:1;
  letter-spacing:calc(0.045em);
  white-space:nowrap;
}

/* ---------- steps ---------- */
.steps{
  display:flex;
  width:100%;
}
.steps.col{flex-direction:column;}
.steps.row{flex-direction:row;align-items:flex-start;}
.step{
  display:flex;align-items:center;
  gap:calc(16px * var(--s));
  min-width:0;
}
.steps.row .step{flex:1 1 0;align-items:center;padding-right:calc(14px * var(--s));}
.step img{
  width:calc(40px * var(--s));
  height:calc(40px * var(--s));
  display:block;flex:0 0 auto;
}
.step .t{
  color:#22305c;
  font-weight:600;
  font-size:calc(28px * var(--s));
  line-height:1.2;
  letter-spacing:calc(-0.005em);
}
.steps.col .step .t{white-space:nowrap;}

/* ---------- footer ---------- */
.footer{
  width:100%;
  background:var(--navy);
  color:#ffffff;
  text-align:center;
  font-weight:500;
  font-size:calc(21px * var(--s));
  line-height:1.3;
  letter-spacing:calc(0.01em);
  padding:calc(20px * var(--s)) calc(10px * var(--s));
  flex:0 0 auto;
  white-space:nowrap;
}
.sp{flex:0 0 auto;}
</style></head>
<body>
<div class="flyer" id="flyer">
  <div class="sp" id="sp0"></div>
  <div class="band inset" id="sec-head">
    <h1 class="head">Proven <span class="hl">RESULTS</span> for <span class="hl">WILLOWMERE</span> Families</h1>
    <div class="rule"></div>
  </div>
  <div class="sp" id="sp1"></div>
  <div class="photo band" id="sec-photo"><img src="photo.png" alt=""></div>
  <div class="sp" id="sp2"></div>
  <div class="cands band inset" id="sec-cands">
    <div class="cand"><div class="name">Dana Levi</div><div class="role">Mayor</div></div>
    <div class="cand"><div class="name">Omar Haddad</div><div class="role">Council</div></div>
    <div class="cand"><div class="name">Ruth Cohen</div><div class="role">Council</div></div>
  </div>
  <div class="sp" id="sp3"></div>
  <div class="cta band" id="sec-cta">
    <img src="mail.svg" alt="">
    <div class="txt">VOTE BY MAIL</div>
  </div>
  <div class="sp" id="sp4"></div>
  <div class="steps band inset ${cfg.stepsDir}" id="sec-steps">
    <div class="step"><img src="check.svg" alt=""><div class="t">Request your ballot<br class="br">&nbsp;by October 20</div></div>
    <div class="sp" id="st1"></div>
    <div class="step"><img src="check.svg" alt=""><div class="t">Fill it out at home</div></div>
    <div class="sp" id="st2"></div>
    <div class="step"><img src="check.svg" alt=""><div class="t">Mail it back<br class="br">&nbsp;by November 3</div></div>
  </div>
  <div class="sp" id="sp5"></div>
  <div class="footer band" id="sec-footer">Paid for by Willowmere Forward &middot; willowmereforward.org</div>
</div>
<script>
const CFG = ${JSON.stringify(cfg)};
const S = CFG.s, V = CFG.h;

function fit(){
  const stepsRow = CFG.stepsDir === 'row';
  // step inner gaps
  const stepGapBase = stepsRow ? 0 : 26;
  document.getElementById('st1').style.height = (stepGapBase*S)+'px';
  document.getElementById('st2').style.height = (stepGapBase*S)+'px';

  // base outer gaps (in master px), index = sp0..sp5
  const gapBase = [40, 34, 34, 34, 36, 34];
  const photoBase = CFG.photoBase;

  const setGaps = (arr)=>arr.forEach((g,i)=>{
    document.getElementById('sp'+i).style.height = Math.max(0,g)+'px';
  });
  const photoEl = document.getElementById('sec-photo');

  let gaps = gapBase.map(g=>g*S);
  let photo = photoBase*S;
  setGaps(gaps); photoEl.style.height = photo+'px';

  const measure = ()=>{
    let t = 0;
    ['sec-head','sec-cands','sec-cta','sec-steps','sec-footer'].forEach(id=>{
      t += document.getElementById(id).getBoundingClientRect().height;
    });
    return t;
  };

  const fixed = measure();            // everything except photo + outer gaps
  const gapSum = gaps.reduce((a,b)=>a+b,0);
  let leftover = V - fixed - photo - gapSum;

  if (leftover > 0){
    // photo absorbs up to 45% of slack, capped at +110% of its base
    const addPhoto = Math.min(leftover*0.45, photo*1.1);
    photo += addPhoto;
    leftover -= addPhoto;
    const total = gaps.reduce((a,b)=>a+b,0);
    gaps = gaps.map(g => g + leftover * (g/total));
  } else {
    let need = -leftover;
    // 1. shrink gaps down to 45% of base
    const minG = gaps.map(g=>g*0.45);
    const avail = gaps.reduce((a,b)=>a+b,0) - minG.reduce((a,b)=>a+b,0);
    const take = Math.min(need, avail);
    const total = gaps.reduce((a,b)=>a+b,0);
    gaps = gaps.map(g => g - take*(g/total));
    need -= take;
    // 2. shrink photo (never below 45% of base)
    if (need > 0){
      const p = Math.min(need, photo*0.55);
      photo -= p; need -= p;
    }
    if (need > 0) console.warn('OVERFLOW remaining', need);
  }
  setGaps(gaps);
  photoEl.style.height = Math.round(photo)+'px';
  window.__fit = {fixed, photo, gaps, leftover, total: measure()+photo+gaps.reduce((a,b)=>a+b,0)};
}

document.fonts.ready.then(()=>{ fit(); document.documentElement.setAttribute('data-ready','1'); });
</script>
</body></html>`;

for (const z of SIZES) {
  const cfg = {
    ...z,
    stepsDir: z.w / z.h >= 1.1 ? 'row' : 'col',
    photoBase: 320,
  };
  fs.writeFileSync(`${z.name}.html`, html(cfg));
  console.log('wrote', z.name + '.html', JSON.stringify(cfg));
}

